import React from "react";
import { Row, Col, Badge } from "react-bootstrap";
import { FaUser, FaLink, FaFilePdf, FaGithub, FaGraduationCap } from "react-icons/fa";
import "./PublicationCard.css";

// Hide specific tags that the user no longer wants to display
const HIDDEN_TAGS = [
  "System bias",
  "Generative AI",
  "Opioid crisis",
  "Digital Media",
  "Social bot",
];

const CitationBadge = ({ count }) => {
  const getColor = (c) => {
    if (c >= 50) return `conic-gradient(#d9534f ${c * 3.6}deg, #f0f0f0 0deg)`;
    if (c >= 20) return `conic-gradient(#f0ad4e ${c * 3.6}deg, #f0f0f0 0deg)`;
    if (c >= 10) return `conic-gradient(#5bc0de ${c * 3.6}deg, #f0f0f0 0deg)`;
    return `conic-gradient(#5cb85c ${c * 3.6}deg, #f0f0f0 0deg)`;
  };

  return (
    <div className="citation-badge-container">
      <div className="citation-badge" style={{ background: getColor(count) }}>
        <div className="citation-count">{count}</div>
      </div>
    </div>
  );
};

const PublicationCard = ({ pub }) => {
  const pubLink = pub?.links?.doi || pub?.links?.scholar;
  return (
    <Row className="publication-card">
      <Col md={2} className="pub-date-col">
        <div className="pub-date">{pub.year}</div>
      </Col>
      <Col md={8} className="pub-details-col">
        <h5 className="pub-title" style={{ textAlign: 'left' }}>
          {pubLink ? (
            <a href={pubLink} target="_blank" rel="noopener noreferrer">
              {pub.title}
            </a>
          ) : (
            pub.title
          )}
        </h5>
        <div className="pub-authors">
          {pub.authors.map((author, index) => {
            // Check for both "Wang, R." and "R Wang" formats
            const isRuiWang = author.includes("Wang, R.") || author.includes("R Wang");
            return (
              <span
                key={index}
                className={isRuiWang ? "author-bold" : ""}
              >
                <FaUser className="author-icon" /> {author}
                {index < pub.authors.length - 1 ? ", " : ""}
              </span>
            );
          })}
        </div>
        <div className="pub-venue">
          <em>{pub.venue}</em>
        </div>
        <div className="pub-links">
          {pub.links.scholar && (
            <a href={pub.links.scholar} target="_blank" rel="noopener noreferrer">
              <FaGraduationCap /> Scholar
            </a>
          )}
          {pub.links.doi && (
            <a href={pub.links.doi} target="_blank" rel="noopener noreferrer">
              <FaLink /> DOI
            </a>
          )}
          {pub.links.pdf && (
            <a href={pub.links.pdf} target="_blank" rel="noopener noreferrer">
              <FaFilePdf /> PDF
            </a>
          )}
          {pub.links.github && (
            <a
              href={pub.links.github}
              target="_blank"
              rel="noopener noreferrer"
            >
              <FaGithub /> GitHub
            </a>
          )}
        </div>
        <div className="pub-tags">
          {pub.tags
            .filter((tag) => !HIDDEN_TAGS.includes(tag))
            .map((tag) => (
              <Badge bg="secondary" key={tag}>
                {tag}
              </Badge>
            ))}
        </div>
      </Col>
      <Col md={2} className="pub-citation-col">
        <CitationBadge count={pub.citations} />
      </Col>
    </Row>
  );
};

export default PublicationCard;
